<?php
namespace CloudHost247\Ovh\Services;use WHMCS\Database\Capsule;use RuntimeException;
final class Synchronizer
{private$r;function __construct(ConnectionResolver$r){$this->r=$r;}function services($endpointId){$lock=new ExecutionLock('services-'.$endpointId);if(!$lock->acquire())throw new RuntimeException('Service synchronization is already running.');$run=Capsule::table('mod_cloudhost247_ovh_sync_runs')->insertGetId(array('sync_type'=>'services','status'=>'running','started_at'=>date('Y-m-d H:i:s')));$counts=array('created_count'=>0,'updated_count'=>0,'unchanged_count'=>0,'failed_count'=>0,'skipped_count'=>0);try{$c=$this->r->endpoint($endpointId);$remote=array();foreach(array('dedicated'=>$c->get('/dedicated/server'),'vps'=>$c->get('/vps'))as$family=>$names)foreach((array)$names as$name)$remote[]=array($family,(string)$name);foreach($remote as$item){list($family,$name)=$item;$binding=Capsule::table('mod_cloudhost247_ovh_services')->where('endpoint_id',$endpointId)->where('remote_service_name',$name)->first();if(!$binding){$counts['skipped_count']++;continue;}try{$path=$family==='vps'?'/vps/'.rawurlencode($name):'/dedicated/server/'.rawurlencode($name);$details=$c->get($path);$status=(string)($details['state']??$details['status']??'active');$old=hash('sha256',(string)$binding->details_json);$json=json_encode($details);Capsule::table('mod_cloudhost247_ovh_services')->where('id',$binding->id)->update(array('family'=>$family,'status'=>$status,'details_json'=>$json,'last_synced_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')));$counts[hash('sha256',$json)===$old?'unchanged_count':'updated_count']++;}catch(\Throwable$e){$counts['failed_count']++;}}$status=$counts['failed_count']?'partial':'success';Capsule::table('mod_cloudhost247_ovh_sync_runs')->where('id',$run)->update(array_merge($counts,array('status'=>$status,'finished_at'=>date('Y-m-d H:i:s'))));return$counts;}catch(\Throwable$e){Capsule::table('mod_cloudhost247_ovh_sync_runs')->where('id',$run)->update(array('status'=>'failed','failed_count'=>1,'error_message'=>substr($e->getMessage(),0,1000),'finished_at'=>date('Y-m-d H:i:s')));throw$e;}finally{$lock->release();}}}
